import numpy as np
from PIL import Image

def load(path):
    return np.array(Image.open(path).convert('RGB'))

def mask_color(a, ref, tol=40):
    d = np.abs(a.astype(int) - np.array(ref, dtype=int)).sum(axis=2)
    return d < tol

def erode(m, iters=1):
    for _ in range(iters):
        m = m[1:-1,1:-1] & m[:-2,1:-1] & m[1:,1:-1] & m[1:-1,:-2] & m[1:-1,2:]
    return np.pad(m[2:-2,2:-2] if False else _center(m, iters*0), 0) if False else _erode(m, iters)

def _erode(m, iters):
    m = m.copy()
    for _ in range(iters):
        out = np.zeros_like(m)
        out[1:-1,1:-1] = m[1:-1,1:-1] & m[:-2,1:-1] & m[2:,1:-1] & m[1:-1,:-2] & m[1:-1,2:]
        m = out
    return m

def fill_holes(m):
    # flood from border on ~m; unfilled background inside = hole
    from collections import deque
    H,W = m.shape
    bg = ~m
    seen = np.zeros_like(bg)
    q = deque()
    for x in range(W):
        for y in (0, H-1):
            if bg[y,x] and not seen[y,x]:
                seen[y,x]=1; q.append((y,x))
    for y in range(H):
        for x in (0, W-1):
            if bg[y,x] and not seen[y,x]:
                seen[y,x]=1; q.append((y,x))
    while q:
        y,x = q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and bg[ny,nx] and not seen[ny,nx]:
                seen[ny,nx]=1; q.append((ny,nx))
    return m | (~bg & ~seen)

def label(m):
    H,W = m.shape
    lab = np.zeros((H,W), int)
    comp = []
    nxt = 1
    for i in range(H):
        row = m[i]
        for j in range(W):
            if row[j] and lab[i,j]==0:
                stack=[(i,j)]; lab[i,j]=nxt; pts=[]
                while stack:
                    y,x = stack.pop(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and m[ny,nx] and lab[ny,nx]==0:
                            lab[ny,nx]=nxt; stack.append((ny,nx))
                comp.append(pts)
                nxt+=1
    return lab, comp

def stats(m, pts):
    ys = [p[0] for p in pts]; xs=[p[1] for p in pts]
    y0,y1,x0,x1 = min(ys),max(ys),min(xs),max(xs)
    area = len(pts)
    bbox = (x0,y0,x1,y1)
    sub = m[y0:y1+1, x0:x1+1]
    return dict(area=area, cx=sum(xs)/area, cy=sum(ys)/area, bbox=bbox,
                fill=area/((y1-y0+1)*(x1-x0+1)),
                w=x1-x0+1, h=y1-y0+1)

def corner_occ(m, x0,y0,x1,y1, k=3):
    # fraction of marker pixels in the 4 corner kxk boxes of the bbox
    tot = 0; cor = 0
    for cy0,cy1,cx0,cx1 in [(y0,y0+k,x0,x0+k),(y0,y0+k,x1-k+1,x1),(y1-k+1,y1,x0,x0+k),(y1-k+1,y1,x1-k+1,x1)]:
        tot += k*k
        cor += int(m[cy0:cy1+1, cx0:cx1+1].sum())
    return cor/tot if tot else 0

def calx(px, t1, t2):
    p1,v1 = t1; p2,v2 = t2
    return v1 + (px-p1)/(p2-p1)*(v2-v1)

def caly(py, t1, t2, scale='linear'):
    p1,v1 = t1; p2,v2 = t2
    if scale=='log':
        l1,l2 = np.log10(v1), np.log10(v2)
        return 10**(l1 + (py-p1)/(p2-p1)*(l2-l1))
    return v1 + (py-p1)/(p2-p1)*(v2-v1)
