from PIL import Image
import numpy as np
im=np.asarray(Image.open('images/fig_016.png').convert('RGB'))
def sat(px):
    r,g,b=px;return max(r,g,b)-min(r,g,b)
# Legend glyph region approx x 382..398, y 30..250. Find each marker center and dominant color
cands=[]
for y in range(30,255):
    band=im[y,382:400]
    sp=[px for px in band if sat(px)>40 and max(px)>90]
    if len(sp)>=3:
        cands.append(y)
# group
groups=[];cur=[];prev=None
for y in cands:
    if prev is not None and y-prev<=4 and cur: cur.append(y)
    else:
        if cur: groups.append(cur)
        cur=[y]
    prev=y
if cur: groups.append(cur)
print('n bands',len(groups))
for g in groups:
    yc=sum(g)/len(g)
    # collect all colored pixels in this band
    pix=[]
    for y in g:
        for x in range(380,402):
            px=im[y,x]
            if sat(px)>40 and max(px)>90: pix.append(tuple(int(v) for v in px))
    pix=np.array(pix)
    # pick the most saturated pixel as marker color
    i=np.argmax(pix.max(1)-pix.min(1))
    print('yc=%.0f  ncol=%d  peak=%s  mean=%s'%(yc,len(pix),pix[i].tolist(),pix.mean(0).astype(int).tolist()))
