from PIL import Image
import numpy as np
from collections import deque

im = Image.open('images/fig_016.png').convert('RGB')
a = np.array(im).astype(int)
r,g,b = a[:,:,0],a[:,:,1],a[:,:,2]

masks = {
 'red':    (r>140)&(r-g>50)&(r-b>40),
 'green':  (g-r>25)&(g-b>15)&(g>100),
 'purple': (b-g>25)&(r-g>5)&(b>85)&(r>55),
}

def label(m):
    H,W=m.shape; lab=-np.ones((H,W),int); n=0
    for i in range(H):
        for j in range(W):
            if m[i,j] and lab[i,j]<0:
                q=deque([(i,j)]); lab[i,j]=n; pix=[]
                while q:
                    y,x=q.popleft(); pix.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and m[ny,nx] and lab[ny,nx]<0:
                                lab[ny,nx]=n; q.append((ny,nx))
                n+=1
    return lab,n

for name,m in masks.items():
    # data region only
    md = m.copy()
    md[:, :112] = False
    md[:, 412:] = False
    lab,n = label(md)
    comps=[]
    for k in range(n):
        ys,xs=np.where(lab==k)
        if len(xs)<6: continue
        x0,x1,y0,y1=xs.min(),xs.max(),ys.min(),ys.max()
        cx,cy=xs.mean(),ys.mean()
        art=[]
        for y in range(y0,y1+1):
            row=''.join('#' if lab[y,x]==k else '.' for x in range(x0,x1+1))
            art.append(row)
        comps.append((round(cy,1),round(cx,1),len(xs),x1-x0+1,y1-y0+1,art))
    print('=====',name)
    for cy,cx,n,w,h,art in sorted(comps):
        print(f'--- cy={cy} cx={cx} n={n} w={w} h={h}')
        for row in art: print('   ',row)
