import numpy as np
from PIL import Image
im = np.asarray(Image.open('images/fig_016.png').convert('RGB')).astype(int)

def redmask(y0,y1,x0,x1):
    return (im[y0:y1,x0:x1,0]-im[y0:y1,x0:x1,1]>30)&(im[y0:y1,x0:x1,0]>160)&(im[y0:y1,x0:x1,0]-im[y0:y1,x0:x1,2]>20)

def norm(m):
    ys,xs=np.nonzero(m)
    return m[ys.min():ys.max()+1, xs.min():xs.max()+1]

sq = norm(redmask(34,46,414,429))
ci = norm(redmask(55,68,414,429))
st = norm(redmask(78,88,414,429))

# absolute-coordinate canvas covering y 20..55, x 120..160
A0Y,A1Y,A0X,A1X = 20,55,120,160
act = np.zeros((A1Y-A0Y, A1X-A0X), bool)
m = redmask(20,55,120,160)
act[:] = m

def place(can, m, cy, cx):
    h,w = m.shape
    y0 = int(round(cy - h/2)) - A0Y
    x0 = int(round(cx - w/2)) - A0X
    for i in np.nonzero(m)[0]:
        for j in np.nonzero(m)[1]:
            yy,xx = y0+i, x0+j
            if 0<=yy<can.shape[0] and 0<=xx<can.shape[1]:
                can[yy,xx]=True

def iou(a,b): return (a&b).sum()/max(1,(a|b).sum())

cx=137.5
res=[]
for sqc in range(33,42):
    for cic in range(34,46):
        for stc in range(35,49):
            can=np.zeros_like(act)
            place(can,sq,sqc,cx); place(can,ci,cic,cx); place(can,st,stc,cx)
            res.append((iou(can,act),sqc,cic,stc))
res.sort(key=lambda t:-t[0])
for r in res[:10]: print('sq=%d ci=%d st=%d IoU=%.3f'%r)
